/* Compact 3D reflexive-polytope catalogue.
   Coordinates and incidence data are derived from the supplied RefPoly.d3.txt.
   IDs are the 1-based record order in that catalogue. */
(() => {
  'use strict';
  const COUNT = 4319;
  function bytes(s) {
    const raw = atob(s);
    const out = new Uint8Array(raw.length);
    for (let i = 0; i < raw.length; i++) out[i] = raw.charCodeAt(i);
    return out;
  }
  function u16(s) {
    const b = bytes(s), out = new Uint16Array(b.length >> 1);
    for (let i = 0; i < out.length; i++) out[i] = b[i * 2] | (b[i * 2 + 1] << 8);
    return out;
  }
  function u32(s) {
    const b = bytes(s), out = new Uint32Array(b.length >> 2);
    for (let i = 0; i < out.length; i++) {
      const j = i * 4;
      out[i] = (b[j] | (b[j + 1] << 8) | (b[j + 2] << 16) | (b[j + 3] << 24)) >>> 0;
    }
    return out;
  }
  function nibble(data, index) {
    const value = data[index >> 1];
    return (index & 1) ? value >>> 4 : value & 15;
  }
  const VC =
    "";
  const XYZ =
    "" +
    "" +
    "" +
    "" +
    "" +
    "" +
    "" +
    "" +
    "" +
    "" +
    "" +
    "";
  const FO =
    "" +
    "";
  const FD =
    "" +
    "" +
    "" +
    "" +
    "" +
    "" +
    "" +
    "" +
    "";
  const PIC =
    "";
  const COR =
    "";
  const SYM =
    "";
  const DUAL =
    "";
  const OO =
    "";
  const OT =
    "" +
    "" +
    "" +
    "" +
    "" +
    "" +
    "" +
    "";
  const SO =
    "";
  const SV =
    "";
  const vertexCountPacked = bytes(VC);
  const vertexCounts = new Uint8Array(COUNT);
  const vertexOffsets = new Uint32Array(COUNT + 1);
  for (let i = 0; i < COUNT; i++) {
    vertexCounts[i] = nibble(vertexCountPacked, i);
    vertexOffsets[i + 1] = vertexOffsets[i] + vertexCounts[i];
  }
  const coordinates = new Int8Array(bytes(XYZ).buffer);
  const faceOffsets = u32(FO);
  const facePacked = bytes(FD);
  const picard = bytes(PIC);
  const cor = bytes(COR);
  const symmetry = bytes(SYM);
  const dual = u16(DUAL);
  const outOffsets = u16(OO);
  const outTargets = u16(OT);
  const sectionOffsets = u16(SO);
  const sectionPacked = bytes(SV);

  function getPoly(index) {
    if (!Number.isInteger(index) || index < 0 || index >= COUNT) return null;
    const n = vertexCounts[index], start = vertexOffsets[index] * 3;
    const points = new Array(n);
    for (let j = 0; j < n; j++) {
      const k = start + j * 3;
      points[j] = [coordinates[k], coordinates[k + 1], coordinates[k + 2]];
    }
    let cursor = faceOffsets[index];
    const faceCount = nibble(facePacked, cursor++);
    const faces = new Array(faceCount);
    for (let f = 0; f < faceCount; f++) {
      const size = nibble(facePacked, cursor++);
      const face = new Array(size);
      for (let j = 0; j < size; j++) face[j] = nibble(facePacked, cursor++);
      faces[f] = face;
    }
    return {
      id: index + 1,
      points,
      faces,
      picard: picard[index],
      cor: cor[index],
      symmetry: symmetry[index],
      dual: dual[index]
    };
  }
  function getSections(index) {
    const start = sectionOffsets[index], end = sectionOffsets[index + 1];
    const result = new Array(end - start);
    for (let i = start; i < end; i++) result[i - start] = nibble(sectionPacked, i);
    return result;
  }
  function getSuccessors(index) {
    return outTargets.subarray(outOffsets[index], outOffsets[index + 1]);
  }
  window.REFLEXIVE_LIBRARY = {
    count: COUNT,
    vertexCounts,
    vertexOffsets,
    outOffsets,
    outTargets,
    dual,
    getPoly,
    getSections,
    getSuccessors
  };
})();
